"""Hindi A1 foundation data for JUBA LISAN."""
from app.data._types import CurriculumUnit, GrammarExample, GrammarTopic, VocabularyEntry, VocabularySet, PhrasebookCategory, PhrasebookEntry, AssessmentQuestion

def _g(slug,title,summary,examples):
    return GrammarTopic(slug=slug,title=title,level="A1",category="core",summary=summary,explanation=summary,examples=[GrammarExample(text=x) for x in examples])
GRAMMAR_TOPICS=[_g(*x) for x in [["pronouns","Personal pronouns","Use मैं, तुम, आप, वह and हम.",["मैं छात्र हूँ।","आप कैसे हैं?"]],["gender","Gender agreement","Match common adjective and verb forms.",["लड़का अच्छा है।","लड़की अच्छी है।"]],["copula","Basic copula","Use हूँ, है and हैं.",["मैं शिक्षक हूँ।","वे छात्र हैं।"]],["questions","Question words","Use क्या, कौन, कहाँ, कब and कैसे.",["यह क्या है?","आप कहाँ हैं?"]],["negation","Negation","Use नहीं in common negative patterns.",["मैं व्यस्त नहीं हूँ।","यह मेरा घर नहीं है।"]],["postpositions","Postpositions","Use में, पर, से and के साथ.",["किताब मेज़ पर है।","मैं घर में हूँ।"]],["habitual","Present habitual","Talk about routines.",["मैं रोज़ पढ़ता हूँ।","वह चाय पीती है।"]],["requests","Polite requests","Make practical polite requests.",["कृपया बैठिए।","कृपया दोहराइए।"]]]]
