ASSESSMENT_BANK=[AssessmentQuestion(id=f"hi-a1-{i:03}",skill=s,difficulty="A1",question=q,options=o,correct=c) for i,(s,q,o,c) in enumerate([["vocabulary","What does नमस्ते mean?",["hello","thanks","water","station"],"hello"],["vocabulary","What does धन्यवाद mean?",["thank you","goodbye","friend","house"],"thank you"],["grammar","Choose 'I am a student'.",["मैं छात्र हूँ।","मैं छात्र है।","मैं छात्र हैं।","मैं छात्र नहीं।"],"मैं छात्र हूँ।"],["grammar","Which sentence is negative?",["यह मेरा घर नहीं है।","यह मेरा घर है।","घर बड़ा है।","आप कहाँ हैं?"],"यह मेरा घर नहीं है।"],["vocabulary","What is माँ?",["mother","brother","friend","bread"],"mother"],["grammar","Which asks 'Where are you?'",["आप कहाँ हैं?","आप कौन हैं?","यह क्या है?","आप कैसे हैं?"],"आप कहाँ हैं?"],["vocabulary","What does कीमत mean?",["price","help","morning","name"],"price"],["reading","किताब मेज़ पर है। Where is the book?",["On the table","At the station","In the street","At work"],"On the table"],["communication","Which is polite?",["कृपया बैठिए।","नमस्ते।","कल आऊँगा।","यह घर है।"],"कृपया बैठिए।"],["communication","What can you say if you do not understand?",["मैं समझ नहीं रहा हूँ।","धन्यवाद।","मेरा नाम अजय है।","दाएँ जाइए।"],"मैं समझ नहीं रहा हूँ।"]],1)]
